package com.spark.falcon.inventory.service;import com.spark.falcon.inventory.entity.InventoryAuditEvent;import com.spark.falcon.inventory.repository.InventoryAuditEventRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;
@Service @RequiredArgsConstructor public class InventoryAuditQueryService{private final InventoryAuditEventRepository repository;@Transactional(readOnly=true)public List<InventoryAuditEvent>timeline(String type,Long id){return repository.findAllByOperationTypeAndOperationIdOrderByOccurredAtAsc(type,id);}}
